def-hyp(
    __list__(
        Type.annotation(@n, Nat),
        Type.annotation(@x_n, Type.to(Nat, S@Topology.ctxt.S))
    ),
    Topology.sequentialCompact(x_n),
    Logic.exists-typed(
        @p,
        Type.to(Nat, Nat),
        Logic.exists-typed(@x, S@Topology.ctxt.S, Topology.seqConvergence(Type.apply(x_n, p), x))
    )
)
